using System;
using System.Collections.Generic;
using System.Linq;
using NetScope;
class DiagnosticsTests {
 static int passed;
 static DateTime now=new DateTime(2026,10,29,12,0,0,DateTimeKind.Utc);
 static ProbeResult P(string id,int? code,bool reach,string group="AI",double? ms=100,string outcome=null){return new ProbeResult{At=now,TargetId=id,Name=id,Url="https://"+id+".example/",StatusCode=code,Reachable=reach,Group=group,HttpMs=ms,DnsMs=5,TcpMs=20,Outcome=outcome??(reach?"OK":"Timeout")};}
 static MonitorFrame F(params ProbeResult[] ps){return new MonitorFrame{At=now,Local=new LocalSample{Gateway="192.168.1.1",Adapters=new List<AdapterInfo>{new AdapterInfo{Id="phy",Type="Ethernet",IsUp=true,IsVirtual=false}}},GatewayMs=5,Probes=ps.ToList()};}
 static List<Finding> E(MonitorFrame f,List<HistoryPoint> h=null){return NetScope.Diagnostics.Evaluate(f,h??new List<HistoryPoint>());}
 static HistoryPoint H(ProbeResult p,int ago){p.At=now.AddSeconds(-ago);return new HistoryPoint{At=p.At,Probes=new List<ProbeResult>{p}};}
 static void Test(string name,Action a){try{a();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){Console.Error.WriteLine("FAIL "+name+": "+ex.Message);Environment.Exit(1);}}
 static void Yes(bool condition,string why){if(!condition)throw new Exception(why);}
 static bool Has(List<Finding> f,string prefix){return f.Any(x=>x.Key.StartsWith(prefix,StringComparison.Ordinal));}
 static void Main(){
 Test("empty input",()=>{Yes(E(null).Count==0,"null should be empty");Yes(NetScope.Diagnostics.Summarize(null).Contains("暂无历史采样"),"empty summary");});
 foreach(int status in new[]{401,403,404,405}){int s=status;Test("HTTP "+s+" is response",()=>{var x=E(F(P("a",s,true)));Yes(!Has(x,"transport:"),"must not report transport failure");Yes(!x.Any(y=>y.Severity=="warning"||y.Severity=="critical"),"restriction not network failure");Yes(Has(x,"http:restriction:"),"must explain limitation");});}
 Test("status overrides inconsistent reach flag",()=>{var x=E(F(P("a",401,false)));Yes(!Has(x,"transport:"),"HTTP code is evidence");});
 Test("429 is scoped rate limiting",()=>{var x=E(F(P("a",429,true)));var f=x.First(y=>y.Key.StartsWith("http:429:"));Yes(f.Severity=="warning","warning needed");Yes(f.Evidence.Contains("CDN")&&f.Evidence.Contains("未证明"),"must qualify origin and quota");Yes(!Has(x,"transport:"),"429 received");});
 Test("5xx includes proxy/CDN uncertainty",()=>{var x=E(F(P("a",503,true)));var f=x.First(y=>y.Key.StartsWith("http:5xx:"));Yes(f.Evidence.Contains("CDN")&&f.Evidence.Contains("代理"),"scope qualified");Yes(!Has(x,"transport:"),"5xx received");});
 Test("redirect not final site success",()=>{var x=E(F(P("a",302,true)));Yes(x.Any(f=>f.Key.StartsWith("http:redirect:")&&f.Evidence.Contains("尚未验证最终页面")),"redirect not followed");});
 Test("ICMP timeout cannot imply outage",()=>{var f=F(P("a",200,true));f.GatewayMs=null;var x=E(f);Yes(!x.Any(y=>y.Severity=="warning"||y.Severity=="critical"),"HTTP succeeded");Yes(x.Any(y=>y.Key=="gateway:no-icmp"&&y.Evidence.Contains("不能据此")),"explanation needed");});
 Test("proxy HTTP success despite local DNS TCP failure",()=>{var p=P("a",200,true);p.DnsMs=null;p.TcpMs=null;p.Error="DNS failed; direct TCP failed";var x=E(F(p));Yes(!Has(x,"transport:"),"don't use unrelated error string");Yes(!x.Any(f=>f.Severity=="critical"||f.Severity=="warning"),"actual route responds");Yes(Has(x,"path:proxy-difference:"),"path explanation");});
 Test("two other targets fail with domestic control",()=>{var x=E(F(P("cn",200,true,"国内"),P("a",null,false),P("b",null,false)));Yes(Has(x,"path:shared-external"),"correlation detected");Yes(!x.Any(f=>f.Severity=="critical"),"one round not severe");Yes(x.First(f=>f.Key=="path:shared-external").Advice.Contains("目前还不能确定"),"do not blame vendor");});
 Test("repeated independent failures severity",()=>{var h=new List<HistoryPoint>{H(P("a",null,false),30),H(P("b",null,false),30)};var x=E(F(P("cn",200,true,"国内"),P("a",null,false),P("b",null,false)),h);Yes(x.Any(f=>f.Key=="path:shared-external"&&f.Severity=="critical"),"two rounds corroborate repeated condition");});
 Test("pause gap not continuous outage",()=>{var h=new List<HistoryPoint>{H(P("a",null,false),3600),H(P("b",null,false),3600)};var x=E(F(P("cn",200,true,"国内"),P("a",null,false),P("b",null,false)),h);Yes(!x.Any(f=>f.Severity=="critical"),"one-hour pause not repeated adjacent failure");});
 Test("single target isolated",()=>{var x=E(F(P("a",null,false),P("b",200,true)));Yes(Has(x,"path:isolated:"),"isolation clue");Yes(!Has(x,"path:all-failed"),"not global outage");});
 Test("invalid URL excluded from network failure",()=>{var x=E(F(P("a",null,false,"AI",null,"InvalidUrl"),P("b",200,true)));Yes(Has(x,"config:"),"configuration notice");Yes(!Has(x,"transport:")&&!Has(x,"path:isolated:"),"not a network observation");});
 Test("minimum baseline sample count",()=>{var h=Enumerable.Range(1,4).Select(i=>H(P("a",200,true,"AI",100),i*30)).ToList();Yes(!Has(E(F(P("a",200,true,"AI",2000)),h),"latency:"),"require five baseline samples");});
 Test("relative latency threshold",()=>{var h=Enumerable.Range(1,6).Select(i=>H(P("a",200,true,"AI",100),i*30)).ToList();Yes(Has(E(F(P("a",200,true,"AI",2000)),h),"latency:"),"regression detected");Yes(!Has(E(F(P("a",200,true,"AI",1000)),h),"latency:"),"absolute floor applies");});
 Test("not all slow responses are historical regression",()=>{var h=Enumerable.Range(1,6).Select(i=>H(P("a",200,true,"AI",1000),i*30)).ToList();Yes(!Has(E(F(P("a",200,true,"AI",2000)),h),"latency:"),"must exceed three times");});
 Test("old target URL is not baseline",()=>{var h=Enumerable.Range(1,6).Select(i=>{var p=P("a",200,true,"AI",100);p.Url="https://old.example/";return H(p,i*30);}).ToList();Yes(!Has(E(F(P("a",200,true,"AI",2000)),h),"latency:"),"config changed baseline isolated");});
 Test("summary counts authentication as HTTP response",()=>{var h=new List<HistoryPoint>{H(P("a",401,true,"AI",100),90),H(P("a",503,true,"AI",300),60),H(P("a",null,false,"AI",null),30)};string s=NetScope.Diagnostics.Summarize(h);Yes(s.Contains("66.7%")&&s.Contains("33.3%"),"2/3 response, 1/3 timeout");Yes(s.Contains("200.0 / 290.0 ms"),"P50 P95 interpolation");Yes(s.Contains("不是网络丢包率"),"distinguish sampling");});
 Test("summary avoids repeated snapshot duplicates",()=>{var p=P("a",401,true);var h=new List<HistoryPoint>{new HistoryPoint{At=now,Probes=new List<ProbeResult>{p}},new HistoryPoint{At=now.AddSeconds(2),Probes=new List<ProbeResult>{p}}};string s=NetScope.Diagnostics.Summarize(h);Yes(s.Contains("1 次有效配置探测"),"same probe not counted twice");});
 Test("no active interface direct evidence",()=>{var f=F();f.Local.Adapters[0].IsUp=false;var x=E(f);Yes(x.Any(y=>y.Key=="local:link"&&y.Severity=="critical"),"local link known down");});
 Test("virtual interface active does not prove VPN healthy",()=>{var f=F();f.Local.Adapters[0].IsVirtual=true;var x=E(f);Yes(x.Any(y=>y.Key=="local:virtual-only"&&y.Advice.Contains("不一定说明")),"do not infer node health");});
 Test("collector skipped is missing measurement not network failure",()=>{var x=E(F(P("skip",null,false,"AI",null,"Skipped"),P("ok",200,true)));Yes(Has(x,"collector:skipped:"),"must explain missing round");Yes(!Has(x,"transport:")&&!Has(x,"path:isolated:"),"must not attribute skipped to service");Yes(!x.Any(f=>f.Severity=="warning"||f.Severity=="critical"),"missing not anomaly");});
 Test("collector skipped excluded from percentages",()=>{var h=new List<HistoryPoint>{H(P("a",200,true),60),H(P("a",null,false,"AI",null,"Skipped"),30)};string s=NetScope.Diagnostics.Summarize(h);Yes(s.Contains("100.0%（1/1）"),"skip entered denominator");Yes(s.Contains("1 次采集器漏测"),"missing data must be disclosed");});
 Test("collector skipped breaks consecutive failure evidence",()=>{var h=new List<HistoryPoint>{H(P("a",null,false,"AI",null,"Skipped"),30),H(P("b",null,false,"AI",null,"Skipped"),30)};var x=E(F(P("cn",200,true,"国内"),P("a",null,false),P("b",null,false)),h);Yes(!x.Any(f=>f.Severity=="critical"),"previous skipped cannot prove repeated failure");});
 Test("path configuration fingerprints isolate latency baseline",()=>{var h=Enumerable.Range(1,6).Select(i=>{var p=P("a",200,true,"AI",100);p.PathId="old-config";return H(p,i*30);}).ToList();var current=P("a",200,true,"AI",2000);current.PathId="new-config";Yes(!Has(E(F(current),h),"latency:"),"different path fingerprints must not share baseline");});
 Test("path change breaks consecutive failure evidence",()=>{var oldA=P("a",null,false);oldA.PathId="old-config";var oldB=P("b",null,false);oldB.PathId="old-config";var a=P("a",null,false);a.PathId="new-config";var b=P("b",null,false);b.PathId="new-config";var x=E(F(P("cn",200,true,"国内"),a,b),new List<HistoryPoint>{H(oldA,30),H(oldB,30)});Yes(!x.Any(f=>f.Severity=="critical"),"old configuration failures are not current continuous evidence");});
 Test("summary preserves intra-bucket peaks",()=>{string s=NetScope.Diagnostics.Summarize(new List<HistoryPoint>{new HistoryPoint{At=now,DownloadBps=1000000,UploadBps=500000,DownloadPeakBps=5000000,UploadPeakBps=2000000,SampleCount=15,SpanSeconds=30}});Yes(s.Contains("下载 40.00 Mbps，上传 16.00 Mbps"),"bucket peak replaced with mean");});
 Test("summary tolerates absent or invalid bucket peaks",()=>{string s=NetScope.Diagnostics.Summarize(new List<HistoryPoint>{new HistoryPoint{At=now,DownloadBps=1000000,UploadBps=500000,DownloadPeakBps=Double.NaN,UploadPeakBps=-1}});Yes(s.Contains("下载 8.00 Mbps，上传 4.00 Mbps"),"invalid peaks should fall back to valid sample");});
 Test("internal collector Error is not service failure",()=>{var x=E(F(P("internal",null,false,"AI",null,"Error"),P("ok",200,true)));Yes(Has(x,"collector:error:"),"must identify internal unknown error");Yes(!Has(x,"transport:")&&!Has(x,"path:isolated:"),"internal error must not implicate service");Yes(!x.Any(f=>f.Severity=="warning"||f.Severity=="critical"),"unknown collector issue is not network outage");});
 Test("internal collector errors excluded from rate denominator",()=>{var h=new List<HistoryPoint>{H(P("a",200,true),60),H(P("a",null,false,"AI",null,"Error"),30)};string s=NetScope.Diagnostics.Summarize(h);Yes(s.Contains("100.0%（1/1）"),"collector error entered denominator");Yes(s.Contains("1 次采集器异常"),"must disclose unknown measurement");});
 Test("internal error cannot establish continuous network failure",()=>{var h=new List<HistoryPoint>{H(P("a",null,false,"AI",null,"Error"),30),H(P("b",null,false,"AI",null,"Error"),30)};var x=E(F(P("cn",200,true,"国内"),P("a",null,false),P("b",null,false)),h);Yes(!x.Any(f=>f.Severity=="critical"),"internal errors are not earlier network failure samples");});
 Test("407 is proxy authentication not provider or transport failure",()=>{var x=E(F(P("a",407,true,"AI",80,"ProxyAuthRequired")));Yes(x.Any(f=>f.Key.StartsWith("proxy:auth:")&&f.Severity=="warning"&&f.Title.Contains("上网通道要求先登录")&&f.Evidence.Contains("不能作为")),"proxy warning missing");Yes(!Has(x,"transport:")&&!Has(x,"http:other:")&&!Has(x,"path:all-failed"),"407 misattributed to transport or vendor");});
 Test("407 cannot support domestic normal control",()=>{var x=E(F(P("cn",407,true,"国内",50,"ProxyAuthRequired"),P("a",null,false),P("b",null,false)));Yes(!Has(x,"path:shared-external"),"407 incorrectly proves domestic control responds");Yes(x.Any(f=>f.Key=="path:all-failed"&&f.Evidence.Contains("目标服务仍未验证")),"no-control finding must retain proxy uncertainty");});
 Test("407 cannot prove another target is an isolated failure",()=>{var x=E(F(P("proxy",407,true,"AI",50,"ProxyAuthRequired"),P("a",null,false)));Yes(!Has(x,"path:isolated:"),"proxy response not a verified target control");});
 Test("only 407 responses do not prove all targets reachable",()=>{var f=F(P("a",407,true,"AI",50,"ProxyAuthRequired"),P("b",407,true,"AI",50,"ProxyAuthRequired"));f.GatewayMs=null;var x=E(f);Yes(x.Count(y=>y.Key.StartsWith("proxy:auth:"))==2,"each target remains unverified");Yes(!x.First(y=>y.Key=="gateway:no-icmp").Evidence.Contains("已有 HTTP 目标返回响应"),"proxy loopback cannot prove external network usable");string s=NetScope.Diagnostics.Summarize(new List<HistoryPoint>{H(P("a",407,true,"AI",50,"ProxyAuthRequired"),30)});Yes(s.Contains("HTTP 响应率 100.0%（1/1）")&&s.Contains("采样传输失败率 0.0%")&&s.Contains("尚未验证目标端点"),"407 needs HTTP-vs-target distinction without false packet loss");});
 Test("proxy auth response excluded from target latency baseline",()=>{var h=Enumerable.Range(1,6).Select(i=>H(P("a",407,true,"AI",10,"ProxyAuthRequired"),i*30)).ToList();Yes(!Has(E(F(P("a",200,true,"AI",2000)),h),"latency:"),"proxy authentication baseline must not imply target slowdown");});
 Console.WriteLine("All "+passed+" diagnostic tests passed.");
 }
}






